import hashlib
import hmac
import time
import os
import threading
import json
from http.server import HTTPServer, BaseHTTPRequestHandler
from urllib.parse import urlparse, parse_qs

SECRET_KEY = os.environ.get('SESSION_SECRET', os.urandom(32).hex())
SESSION_DURATION = 3600

# Thread-safe session store
class SessionStore:
    def __init__(self):
        self._lock = threading.RLock()
        self._sessions = {}
        self._revoked = set()
        # Background cleanup thread
        self._cleanup_thread = threading.Thread(target=self._cleanup_loop, daemon=True)
        self._cleanup_thread.start()

    def _cleanup_loop(self):
        while True:
            time.sleep(60)
            self._purge_expired()

    def _purge_expired(self):
        now = time.time()
        with self._lock:
            expired = [sid for sid, data in self._sessions.items()
                      if data['expires_at'] < now]
            for sid in expired:
                del self._sessions[sid]

    def create_session(self, user_id, roles):
        session_id = os.urandom(16).hex()
        now = time.time()
        session_data = {
            'user_id': user_id,
            'roles': roles,
            'created_at': now,
            'expires_at': now + SESSION_DURATION,
            'last_accessed': now
        }
        mac = self._compute_mac(session_id, session_data)
        session_data['mac'] = mac
        with self._lock:
            self._sessions[session_id] = session_data
        return session_id, mac

    def _compute_mac(self, session_id, data):
        msg = f"{session_id}:{data['user_id']}:{data['expires_at']}"
        return hmac.new(
            SECRET_KEY.encode() if isinstance(SECRET_KEY, str) else SECRET_KEY,
            msg.encode(),
            hashlib.sha256
        ).hexdigest()

    def validate_session(self, session_id, provided_mac):
        """Validate session with integrity check.
        Uses constant-time comparison for MAC verification."""
        with self._lock:
            session = self._sessions.get(session_id)
            if session is None:
                return None
            if session_id in self._revoked:
                return None
            # Check expiration
            if session['expires_at'] < time.time():
                del self._sessions[session_id]
                return None
            stored_mac = session['mac']

        # MAC verification outside lock for performance
        # Recompute expected MAC to verify integrity
        expected_mac = self._compute_mac(session_id, session)
        if not self._safe_compare(expected_mac, provided_mac):
            return None

        # Update last accessed (TOCTOU: session could be modified/deleted between
        # the lock release above and this re-acquisition)
        with self._lock:
            if session_id in self._sessions:
                self._sessions[session_id]['last_accessed'] = time.time()
            return session

    def _safe_compare(self, a, b):
        """Constant-time string comparison to prevent timing attacks."""
        if not isinstance(a, str) or not isinstance(b, str):
            return False
        # Ensure constant-time by always comparing full length
        a_bytes = a.encode('utf-8')
        b_bytes = b.encode('utf-8')
        if len(a_bytes) != len(b_bytes):
            # Still do work to avoid length-based timing leak
            result = 1
            for i in range(max(len(a_bytes), len(b_bytes))):
                result |= a_bytes[i % len(a_bytes)] ^ b_bytes[i % len(b_bytes)]
            return False
        result = 0
        for i in range(len(a_bytes)):
            result |= a_bytes[i] ^ b_bytes[i]
        return result == 0

    def revoke_session(self, session_id):
        with self._lock:
            self._revoked.add(session_id)
            self._sessions.pop(session_id, None)

    def get_active_sessions(self, user_id):
        with self._lock:
            return [
                {'session_id': sid, 'created_at': data['created_at'],
                 'last_accessed': data['last_accessed']}
                for sid, data in self._sessions.items()
                if data['user_id'] == user_id
                and data['expires_at'] >= time.time()
            ]


store = SessionStore()

# Simple user database (in production, use proper password hashing)
USERS = {
    'admin': {'password_hash': hashlib.sha256(b'admin_pass_placeholder').hexdigest(),
              'roles': ['admin', 'user']},
    'alice': {'password_hash': hashlib.sha256(b'alice_pass_placeholder').hexdigest(),
              'roles': ['user']},
}


def verify_password(username, password):
    user = USERS.get(username)
    if user is None:
        # Constant-time: still hash to prevent user enumeration
        hashlib.sha256(password.encode()).hexdigest()
        return False
    expected = user['password_hash']
    actual = hashlib.sha256(password.encode()).hexdigest()
    return hmac.compare_digest(expected, actual)


class AuthHandler(BaseHTTPRequestHandler):
    def do_POST(self):
        path = urlparse(self.path).path
        content_length = int(self.headers.get('Content-Length', 0))
        if content_length > 4096:
            self._respond(413, {'error': 'payload too large'})
            return
        body = self.rfile.read(content_length)

        if path == '/auth/login':
            self._handle_login(body)
        elif path == '/auth/logout':
            self._handle_logout()
        else:
            self._respond(404, {'error': 'not found'})

    def do_GET(self):
        path = urlparse(self.path).path
        session = self._authenticate()
        if session is None:
            self._respond(401, {'error': 'unauthorized'})
            return

        if path == '/api/profile':
            self._respond(200, {
                'user_id': session['user_id'],
                'roles': session['roles']
            })
        elif path == '/api/admin/sessions':
            if 'admin' not in session['roles']:
                self._respond(403, {'error': 'forbidden'})
                return
            params = parse_qs(urlparse(self.path).query)
            target_user = params.get('user', [session['user_id']])[0]
            sessions = store.get_active_sessions(target_user)
            self._respond(200, {'sessions': sessions})
        else:
            self._respond(404, {'error': 'not found'})

    def _handle_login(self, body):
        try:
            data = json.loads(body)
            username = str(data.get('username', ''))
            password = str(data.get('password', ''))
        except (json.JSONDecodeError, TypeError):
            self._respond(400, {'error': 'invalid request'})
            return

        if not username or not password:
            self._respond(400, {'error': 'missing credentials'})
            return

        if len(username) > 64 or len(password) > 128:
            self._respond(400, {'error': 'input too long'})
            return

        if not verify_password(username, password):
            self._respond(401, {'error': 'invalid credentials'})
            return

        user = USERS[username]
        session_id, mac = store.create_session(username, user['roles'])
        self._respond(200, {
            'session_id': session_id,
            'token': mac,
            'expires_in': SESSION_DURATION
        })

    def _handle_logout(self):
        session_id = self.headers.get('X-Session-ID')
        if session_id:
            store.revoke_session(session_id)
        self._respond(200, {'status': 'logged out'})

    def _authenticate(self):
        session_id = self.headers.get('X-Session-ID', '')
        token = self.headers.get('X-Session-Token', '')
        if not session_id or not token:
            return None
        if len(session_id) != 32 or len(token) != 64:
            return None
        return store.validate_session(session_id, token)

    def _respond(self, status, data):
        self.send_response(status)
        self.send_header('Content-Type', 'application/json')
        self.send_header('X-Content-Type-Options', 'nosniff')
        self.send_header('Cache-Control', 'no-store')
        self.end_headers()
        self.wfile.write(json.dumps(data).encode())

    def log_message(self, format, *args):
        pass  # Suppress default logging


